import re

from moler.exceptions import ParsingDone
from moler.helpers import convert_to_number

from ta_moler.cmd.airscale.genericairscale import GenericAirscale


class TrsVppctlShow(GenericAirscale):
    """TrsVppctlShow command class."""

    def __init__(self, options, connection, prompt=None, newline_chars=None, runner=None):
        """
        Trsvppctlshow command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameter with which the show command will be executed
                   interface
                   interface address
                   hardware-interfaces
                   errors
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(TrsVppctlShow, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

        self.options = options
        self.current_ret["RESULT"] = {}
        self.parsed_interface = ""
        self.node = []
        self.reason = []
        self.count = []
        self.rx_val = 0

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "/opt/trs/bin/trs-vppctl show"

        cmd = f"{cmd} {self.options}"

        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._check_interface(line)
                self._check_interface_address(line)
                self._check_hardware_interfaces(line)
                self._check_errors(line)

            except ParsingDone:
                pass

        return super(TrsVppctlShow, self).on_new_line(line, is_full_line)

    def _check_interface(self, line):
        """
        Start parsing methods if parameter options = 'interface'.

        :param line: Line from device.
        :return: None.
        """
        if self.options == "interface":
            self._parse_interface_info(line)
            self._parse_interface_stats(line)

    def _check_errors(self, line):
        """
        Start parsing methods if parameter options = 'errors'.

        :param line: Line from device.
        :return: None.
        """
        if self.options == "errors":
            self._parse_errors(line)

    def _check_interface_address(self, line):
        """
        Start parsing methods if parameter options = 'interface address'.

        :param line: Line from device.
        :return: None.
        """
        if self.options == "interface address":
            self._parse_interface_address_info(line)
            self._parse_rx_packets_val(line)
            self._parse_interface_address_ip_mask(line)

    def _check_hardware_interfaces(self, line):
        """
        Start parsing methods if parameter options = 'hardware-interfaces'.

        :param line: Line from device.
        :return: None.
        """
        if self.options == "hardware-interfaces":
            self._parse_hardware_interface(line)
            self._parse_hardware_mac_adr(line)
            self._parse_hardware_board(line)
            self._parse_carrier(line)
            self._parse_flags(line)
            self._parse_queues_desc(line)
            self._parse_socket(line)
            self._parse_hardware_stats(line)
            self._parse_hardware_ex_stats(line)

    # EthernetSwitch1/0/6               1      up         10000/0/0/0
    _re_interface_info = re.compile(r"^(?P<INTERFACE>\w+.\d.\d|\w+)\s+(?P<IDX>\d)\s+(?P<STATE>\w+)\s+(?P<MTU>\d+.\d+.\d+.\d+)")

    def _parse_interface_info(self, line):
        if self._regex_helper.search_compiled(TrsVppctlShow._re_interface_info, line):
            self.current_ret["RESULT"][self._regex_helper.group("INTERFACE")] = {}
            self.parsed_interface = self._regex_helper.group("INTERFACE")
            self.current_ret["RESULT"][self._regex_helper.group("INTERFACE")]["Idx"] = convert_to_number(self._regex_helper.group("IDX"))
            self.current_ret["RESULT"][self._regex_helper.group("INTERFACE")]["State"] = self._regex_helper.group("STATE")
            self.current_ret["RESULT"][self._regex_helper.group("INTERFACE")]["MTU"] = self._regex_helper.group("MTU")
            self.current_ret["RESULT"][self._regex_helper.group("INTERFACE")]["Counter"] = {}
            self._parse_rx_packets_val(line)

            raise ParsingDone

    # EthernetSwitch2/0/0               2      up       1500/1500/1500/0  rx packets                 25111
    _re_rx_packets_val = re.compile(r".\d\s+rx\spackets\s+(?P<RX_VAL>\d+)")

    def _parse_rx_packets_val(self, line):
        if self._regex_helper.search_compiled(TrsVppctlShow._re_rx_packets_val, line):
            self.rx_val = int(self._regex_helper.group("RX_VAL"))
            self.current_ret["RESULT"][self.parsed_interface]["Counter"]["rx packets"] = self.rx_val

            raise ParsingDone

    #                                                                     rx bytes                 2354717
    _re_interface_stats = re.compile(r"^\s{14}\s+(?P<COUNTER>\w+\s\w+\s\w+|\w+\s\w+-\w+|\w+\s\w+|\w+)\s+(?P<VALUE>\d+)")

    def _parse_interface_stats(self, line):
        if self._regex_helper.search_compiled(TrsVppctlShow._re_interface_stats, line):
            self.current_ret["RESULT"][self.parsed_interface]["Counter"][self._regex_helper.group("COUNTER")] = convert_to_number(
                self._regex_helper.group("VALUE")
            )

            raise ParsingDone

    # EthernetSwitch1/0/6 (up):
    _re_interface_address_info = re.compile(r"^(?P<INTERFACE>\w+.\d.\d|\w+)\s.(?P<LINK>\w+).:")

    def _parse_interface_address_info(self, line):
        if self._regex_helper.search_compiled(TrsVppctlShow._re_interface_address_info, line):
            self.current_ret["RESULT"][self._regex_helper.group("INTERFACE")] = {}
            self.current_ret["RESULT"][self._regex_helper.group("INTERFACE")]["IP"] = []
            self.current_ret["RESULT"][self._regex_helper.group("INTERFACE")]["mask"] = []
            self.current_ret["RESULT"][self._regex_helper.group("INTERFACE")]["link"] = self._regex_helper.group("LINK")
            self.parsed_interface = self._regex_helper.group("INTERFACE")

            raise ParsingDone

    #   L3 <TRSW_65>10.83.182.141</TRSW_65>/23
    _re_interface_address_ip_mask = re.compile(r"(?P<IP>\d+\.\d+\.\d+\.\d+)..\w+..(?P<MASK>\d+)")

    def _parse_interface_address_ip_mask(self, line):
        if self._regex_helper.search_compiled(TrsVppctlShow._re_interface_address_ip_mask, line):
            self.current_ret["RESULT"][self.parsed_interface]["IP"].append(self._regex_helper.group("IP"))
            self.current_ret["RESULT"][self.parsed_interface]["mask"].append(convert_to_number(self._regex_helper.group("MASK")))

            raise ParsingDone

    # EthernetSwitch1/0/6                1     up   EthernetSwitch1/0/6
    _re_hardware_interface_info = re.compile(
        r"^(?P<INTERFACE>\w+\d.\d+.\d+|\w+\d+)\s+(?P<IDX>\d)\s+(?P<STATE>\w+)\s+(?P<HARDWARE>\w+.\d+.\d+|\w+\d+)"
    )

    def _parse_hardware_interface(self, line):
        if self._regex_helper.search_compiled(TrsVppctlShow._re_hardware_interface_info, line):
            self.current_ret["RESULT"][self._regex_helper.group("INTERFACE")] = {}
            self.parsed_interface = self._regex_helper.group("INTERFACE")
            self.current_ret["RESULT"][self._regex_helper.group("INTERFACE")]["Idx"] = convert_to_number(self._regex_helper.group("IDX"))
            self.current_ret["RESULT"][self._regex_helper.group("INTERFACE")]["Link"] = self._regex_helper.group("STATE")
            self.current_ret["RESULT"][self._regex_helper.group("INTERFACE")]["Hardware"] = self._regex_helper.group("HARDWARE")
            self._parse_prep_dict()

            raise ParsingDone

    #   Ethernet address <TRSW_43>02:40:43:80:10:08</TRSW_43>
    _re_mac = re.compile(r"\d+>(?P<MAC>([0-9A-Fa-f]{2}[:-]){5}([0-9A-Fa-f]{2}))")

    def _parse_hardware_mac_adr(self, line):
        if self._regex_helper.search_compiled(TrsVppctlShow._re_mac, line):
            self.current_ret["RESULT"][self.parsed_interface]["Ethernet address"] = self._regex_helper.group("MAC")

            raise ParsingDone

    #   Intel FM10000 Family Ethernet Switch
    _re_board = re.compile(r"^\s\s(?P<BOARD>\w+.+)")

    def _parse_hardware_board(self, line):
        if self._regex_helper.search_compiled(TrsVppctlShow._re_board, line):
            self.current_ret["RESULT"][self.parsed_interface]["board"] = self._regex_helper.group("BOARD")

            raise ParsingDone

    #     carrier up full duplex speed 50000 mtu 9990
    _re_carrier = re.compile(r"^\s+carrier\s(?P<CARRIER>\w+)\s(?P<DUPLEX>\w+)\s\w+\s\w+\s(?P<SPEED>\d+)\s\w+\s(?P<MTU>\d+)")

    def _parse_carrier(self, line):
        if self._regex_helper.search_compiled(TrsVppctlShow._re_carrier, line):
            self.current_ret["RESULT"][self.parsed_interface]["carrier"] = self._regex_helper.group("CARRIER")
            self.current_ret["RESULT"][self.parsed_interface]["duplex"] = self._regex_helper.group("DUPLEX")
            self.current_ret["RESULT"][self.parsed_interface]["speed"] = convert_to_number(self._regex_helper.group("SPEED"))
            self.current_ret["RESULT"][self.parsed_interface]["mtu"] = convert_to_number(self._regex_helper.group("MTU"))

            raise ParsingDone

    #     flags: admin-up pmd maybe-multiseg
    _re_flag = re.compile(r"^\s+flags:\s(?P<FLAGS>.+)")

    def _parse_flags(self, line):
        if self._regex_helper.search_compiled(TrsVppctlShow._re_flag, line):
            table = self._regex_helper.group("FLAGS").split(" ")
            self.current_ret["RESULT"][self.parsed_interface]["flags"] = table

            raise ParsingDone

    #     rx queues 1, rx desc 8192, tx queues 3, tx desc 8192
    _re_queues_desc = re.compile(r"^\s{4}.{10}(?P<rxq>\d+).{10}(?P<rxd>\d+).{12}(?P<txq>\d+).{10}(?P<txd>\d+)")

    def _parse_queues_desc(self, line):
        if self._regex_helper.search_compiled(TrsVppctlShow._re_queues_desc, line):
            self.current_ret["RESULT"][self.parsed_interface]["rx queues"] = convert_to_number(self._regex_helper.group("rxq"))
            self.current_ret["RESULT"][self.parsed_interface]["rx desc"] = convert_to_number(self._regex_helper.group("rxd"))
            self.current_ret["RESULT"][self.parsed_interface]["tx queues"] = convert_to_number(self._regex_helper.group("txq"))
            self.current_ret["RESULT"][self.parsed_interface]["tx desc"] = convert_to_number(self._regex_helper.group("txd"))

            raise ParsingDone

    #     cpu socket 0
    _re_socket = re.compile(r"^\s+cpu\s\w+\s(?P<SOCKET>\d+)")

    def _parse_socket(self, line):
        if self._regex_helper.search_compiled(TrsVppctlShow._re_socket, line):
            self.current_ret["RESULT"][self.parsed_interface]["cpu socket"] = convert_to_number(self._regex_helper.group("SOCKET"))

            raise ParsingDone

    def _parse_prep_dict(self):
        self.current_ret["RESULT"][self.parsed_interface]["rx queues"] = None
        self.current_ret["RESULT"][self.parsed_interface]["rx desc"] = None
        self.current_ret["RESULT"][self.parsed_interface]["tx queues"] = None
        self.current_ret["RESULT"][self.parsed_interface]["tx desc"] = None
        self.current_ret["RESULT"][self.parsed_interface]["cpu socket"] = None
        self.current_ret["RESULT"][self.parsed_interface]["carrier"] = "down"
        self.current_ret["RESULT"][self.parsed_interface]["duplex"] = None
        self.current_ret["RESULT"][self.parsed_interface]["speed"] = None
        self.current_ret["RESULT"][self.parsed_interface]["mtu"] = None
        self.current_ret["RESULT"][self.parsed_interface]["flags"] = []
        self.current_ret["RESULT"][self.parsed_interface]["stats"] = {}
        self.current_ret["RESULT"][self.parsed_interface]["extended stats"] = {}

    #     tx frames ok                                        1745
    _re_stats = re.compile(r"^\s{4}(?P<STATS>\w+\s\w+\s\w+)\s+(?P<VALUE>\d+)")

    def _parse_hardware_stats(self, line):
        if self._regex_helper.search_compiled(TrsVppctlShow._re_stats, line):
            self.current_ret["RESULT"][self.parsed_interface]["stats"][self._regex_helper.group("STATS")] = convert_to_number(
                self._regex_helper.group("VALUE")
            )

            raise ParsingDone

    #       rx good packets                                  26110
    _re_ex_stats = re.compile(r"^\s{6}(?P<EXSTATS>\w+\s\w+\s\w+|\w+\s\w+)\s+(?P<VALUE>\d+)")

    def _parse_hardware_ex_stats(self, line):
        if self._regex_helper.search_compiled(TrsVppctlShow._re_ex_stats, line):
            self.current_ret["RESULT"][self.parsed_interface]["extended stats"][self._regex_helper.group("EXSTATS")] = convert_to_number(
                self._regex_helper.group("VALUE")
            )

            raise ParsingDone

    #      25275               pps-policer              PPS Policer classify hits
    _re_error = re.compile(
        r"^\s+(?P<COUNT>\d+)\s+(?P<NODE>\w+.\w+.\w+|\w+)\s+(?P<REASON>\w+(\s\w+)"
        r"*$|\w+\s\w+\s\w+\s\s-\s\w+\s->\s\w+|\w+\s\w+\s\w+\s\w+\s-\s\w+\s->\s\w+)"
    )

    def _parse_errors(self, line):
        if self._regex_helper.search_compiled(TrsVppctlShow._re_error, line):
            self.count.append(convert_to_number(self._regex_helper.group("COUNT")))
            self.reason.append(self._regex_helper.group("REASON"))
            self.node.append(self._regex_helper.group("NODE"))

            self.current_ret["RESULT"]["Count"] = self.count
            self.current_ret["RESULT"]["Reason"] = self.reason
            self.current_ret["RESULT"]["Node"] = self.node

            raise ParsingDone


